const item = $input.first().json;
const cmd = item.command || "CREATE_REMINDER";
const params = item.parameters || {};
const userId = String(item.userId || item.chatId || "default");
const chatId = item.chatId;

let content = (params && (params.reminder_text || params.content || params.notes)) || item.text || "";
if (typeof content === "string") {
  content = content.replace(/^(?:remind me to|remind me on [A-Za-z0-9\s,]+ to|remind me tomorrow (?:at [A-Za-z0-9:]+ )?to|remind me (?:at [A-Za-z0-9:]+ )?to|create reminder:?|add reminder:?)[:\s]*/i, "").trim();
  if (!content && item.text) content = item.text.trim();
}

let reminderAt = (params && (params.reminder_at || params.follow_up_date || params.due_at || params.due_date));
if (!reminderAt) {
  const d = new Date(Date.now() + 24 * 60 * 60 * 1000);
  reminderAt = d.toISOString();
}

let reminderId = null;
if (params && (params.reminder_id || params.id)) {
  const rawId = String(params.reminder_id || params.id).replace(/[^0-9]/g, "");
  if (rawId) reminderId = parseInt(rawId, 10);
}

const confirmed = params && (params.confirmed === true || String(params.confirmed).toLowerCase() === "true");

return [{
  json: {
    command: cmd,
    chatId,
    userId,
    content,
    reminderAt,
    reminderId,
    confirmed,
    parameters: params,
    text: item.text
  }
}];

const trig = $("Extract Reminder Input").first().json;
const r = $input.first().json;
if (!r || !r.id) {
  return [{ json: { chatId: trig.chatId, text: "⚠️ Failed to create reminder." } }];
}
let dateStr = r.reminder_at;
try {
  const d = new Date(r.reminder_at);
  if (!isNaN(d.getTime())) {
    dateStr = new Intl.DateTimeFormat("en-IN", {
      timeZone: "Asia/Kolkata",
      dateStyle: "medium",
      timeStyle: "short"
    }).format(d);
  }
} catch (e) {}

return [{
  json: {
    chatId: trig.chatId,
    text: `🔔 <b>Reminder set!</b> (ID: #${r.id})\n\n<b>What:</b> ${r.content}\n<b>When:</b> ${dateStr}`,
    reminderId: r.id
  }
}];

const trig = $("Extract Reminder Input").first().json;
const items = $input.all().map(i => i.json).filter(i => i && i.id);
if (items.length === 0) {
  return [{ json: { chatId: trig.chatId, text: "🔔 You don't have any active reminders." } }];
}
const lines = items.map((item, idx) => {
  let dateStr = item.reminder_at;
  try {
    const d = new Date(item.reminder_at);
    if (!isNaN(d.getTime())) {
      dateStr = new Intl.DateTimeFormat("en-IN", {
        timeZone: "Asia/Kolkata",
        dateStyle: "medium",
        timeStyle: "short"
      }).format(d);
    }
  } catch (e) {}
  return `${idx + 1}. (ID: #${item.id}) ⏰ ${dateStr}\n   ${item.content}`;
});
const text = `🔔 <b>YOUR REMINDERS</b>\n\n${lines.join("\n\n")}`;
return [{ json: { chatId: trig.chatId, text } }];

const trig = $("Extract Reminder Input").first().json;
const res = $input.first().json;
if (res && res.id) {
  return [{ json: { chatId: trig.chatId, text: `🗑️ Reminder #${res.id} deleted.` } }];
}
return [{ json: { chatId: trig.chatId, text: "⚠️ Reminder not found or doesn't belong to you." } }];

const trig = $("Extract Reminder Input").first().json;
const count = $input.all().filter(i => i.json && i.json.id).length;
return [{ json: { chatId: trig.chatId, text: `🗑️ Deleted ${count} reminder(s). All your reminders have been cleared.` } }];
